#!/usr/bin/env perl
# Generates perl-lib/GD/Fonts.pm from libgd's built-in bitmap fonts
# (src/gdfont{t,s,mb,l,g}.c in https://github.com/libgd/libgd). The fonts are
# the public domain X11 "misc-fixed" fonts (ISO-8859-2).
#   perl tools/gd-fonts.pl /path/to/libgd/src > perl-lib/GD/Fonts.pm
use strict;
use warnings;

my $src = shift or die "Usage: $0 LIBGD_SRC_DIR\n";
my %files = (Tiny => 'gdfontt.c', Small => 'gdfonts.c', MediumBold => 'gdfontmb.c', Large => 'gdfontl.c', Giant => 'gdfontg.c');

print <<'HEAD';
package GD::Fonts;

# Bitmap fonts for the pure-Perl GD module, generated by tools/gd-fonts.pl from
# libgd's built-in fonts (the public domain X11 misc-fixed fonts, ISO-8859-2).
# Each font: [ number of chars, first char, width, height, hex string of rows ]
# where each glyph row is one byte per pixel column packed as a bit string.

use strict;
use warnings;

our %FONTS = (
HEAD
for my $name (sort keys %files) {
	open my $fh, '<', "$src/$files{$name}" or die "$files{$name}: $!";
	my $c = do { local $/; <$fh> };
	my ($data) = $c =~ /static\s+(?:const\s+)?(?:unsigned\s+)?char\s+\w+\[\]\s*=\s*\{(.*?)\};/s or die "no data in $files{$name}";
	$data =~ s{/\*.*?\*/}{}gs;
	my @px = $data =~ /(\d+)/g;
	my ($nchars, $offset, $w, $h) = $c =~ /gdFont\s+\w+Rep\s*=\s*\{\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/ or die "no rep";
	die "$name: size mismatch" unless @px == $nchars * $w * $h;
	# pack each glyph row into bits, msb first
	my $bits = join '', map { $_ ? '1' : '0' } @px;
	my $hex = unpack('H*', pack('B*', $bits));
	print "\t$name => [ $nchars, $offset, $w, $h,\n\t\t'$hex' ],\n";
}
print ");\n\n1;\n";
